const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 1440, height: 900 } });
  await p.goto('http://localhost:5188/guide/introduction.html', { waitUntil: 'domcontentloaded', timeout: 60000 });
  await p.waitForTimeout(1200);
  const sidebar = await p.evaluate(() => {
    const out = new Map();
    for (const el of document.querySelectorAll('.VPSidebar, .VPSidebar *')) {
      const cs = getComputedStyle(el);
      for (const side of ['Top', 'Bottom']) {
        if (cs[`border${side}Width`] !== '0px' && cs[`border${side}Style`] !== 'none') {
          const key = el.className.toString().slice(0, 50) + '|' + side;
          if (!out.has(key)) out.set(key, cs[`border${side}Color`]);
        }
      }
    }
    return [...out.entries()].slice(0, 8);
  });
  const m = await b.newPage({ viewport: { width: 390, height: 844 } });
  await m.goto('http://localhost:5188/guide/introduction.html', { waitUntil: 'domcontentloaded', timeout: 60000 });
  await m.waitForTimeout(1200);
  await m.click('.VPNavBarHamburger');
  await m.waitForSelector('.VPNavScreen', { state: 'visible' });
  const screen = await m.evaluate(() => {
    const out = new Map();
    for (const el of document.querySelectorAll('.VPNavScreen, .VPNavScreen *')) {
      const cs = getComputedStyle(el);
      for (const side of ['Top', 'Bottom']) {
        if (cs[`border${side}Width`] !== '0px' && cs[`border${side}Style`] !== 'none') {
          const key = el.className.toString().slice(0, 50) + '|' + side;
          if (!out.has(key)) out.set(key, cs[`border${side}Color`]);
        }
      }
    }
    return [...out.entries()].slice(0, 10);
  });
  console.log(JSON.stringify({ sidebar, screen }, null, 1));
  await b.close();
})();
EOF

