24	    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
25	  }
26	
27	  // Validate and store a submission as pending. Returns the stored row
28	  // id; throws with a reader-facing message on invalid input.
29	  static async submit(
30	    env: Env,
31	    submission: { slug: string; name: string; email: string; body: string },
32	  ): Promise<number> {
33	    const slug = String(submission.slug ?? '').trim();
34	    const name = String(submission.name ?? '')
35	      .trim()
36	      .slice(0, this.NAME_MAXIMUM_LENGTH);
37	    const email = String(submission.email ?? '')
38	      .trim()
39	      .toLowerCase();
40	    const body = String(submission.body ?? '').trim();
41	    if (!/^[a-z0-9][a-z0-9-]*$/.test(slug)) throw new Error('Bad post slug.');
42	    if (!name) throw new Error('A name is required.');
43	    if (!this.EMAIL_PATTERN.test(email))
44	      throw new Error('That email address does not look right.');
45	    if (!body) throw new Error('The comment is empty.');
46	    if (body.length > this.BODY_MAXIMUM_LENGTH)
47	      throw new Error(
48	        `Comments are capped at ${this.BODY_MAXIMUM_LENGTH} characters.`,
49	      );
50	    const outcome = await env.DB.prepare(
51	      'INSERT INTO comments (slug, name, email, body, submitted_at, status) ' +
52	        "VALUES (?, ?, ?, ?, ?, 'pending')",
53	    )
54	      .bind(slug, name, email, body, Http.Class.nowSeconds())
55	      .run();
56	    return Number(
57	      (outcome as { meta?: { last_row_id?: number } }).meta?.last_row_id ?? 0,
58	    );
59	  }
60	
61	  // The public read: approved only, oldest first (a conversation reads
62	  // downward), and WITHOUT the email column — the projection is the
63	  // privacy guarantee.
64	  static async approvedFor(env: Env, slug: string): Promise<PublicComment[]> {
65	    const { results } = await env.DB.prepare(
66	      'SELECT id, name, body, submitted_at AS submittedAt FROM comments ' +
67	        "WHERE slug = ? AND status = 'approved' ORDER BY submitted_at",
68	    )
69	      .bind(slug)
70	      .all<PublicComment>();
71	    return results;
72	  }
73	
74	  // The dashboard page: pending first (the moderation queue), then
75	  // newest; optional status filter and recipient/slug/body search.
76	  static async page(env: Env, query: CommentPageQuery): Promise<CommentPage> {
77	    const status = (query.status ?? '').trim();
78	    const search = (query.search ?? '').trim();
79	    const searchPattern = `%${search}%`;
80	    const limit = Math.min(
81	      Math.max(1, query.limit ?? 50),
82	      this.PAGE_LIMIT_MAXIMUM,
83	    );
84	    const offset = Math.max(0, query.offset ?? 0);
85	    const whereClause =
86	      "WHERE (?1 = '' OR status = ?1) " +
87	      "AND (?2 = '' OR slug LIKE ?3 OR name LIKE ?3 OR email LIKE ?3 OR body LIKE ?3)";
88	    const [{ results: rows }, totalRow] = await Promise.all([
89	      env.DB.prepare(
90	        'SELECT id, slug, name, email, body, submitted_at AS submittedAt, status ' +
91	          'FROM comments ' +
92	          whereClause +
93	          " ORDER BY CASE status WHEN 'pending' THEN 0 ELSE 1 END, submitted_at DESC " +
94	          'LIMIT ?4 OFFSET ?5',
95	      )
96	        .bind(status, search, searchPattern, limit, offset)
97	        .all<CommentRow>(),
98	      env.DB.prepare('SELECT COUNT(*) AS total FROM comments ' + whereClause)
99	        .bind(status, search, searchPattern)
100	        .first<{ total: number }>(),
101	    ]);
102	    return { total: totalRow?.total ?? 0, rows, limit, offset };
103	  }
104	
105	  static async pendingCount(env: Env): Promise<number> {
106	    const row = await env.DB.prepare(
107	      "SELECT COUNT(*) AS total FROM comments WHERE status = 'pending'",
108	    ).first<{ total: number }>();
109	    return row?.total ?? 0;
