}

export interface PublicComment {
  id: number;
  name: string;
  body: string;
  submittedAt: number;
  parentId: number | null;
  rootId: number | null;
  locked: number;
  avatarSeed: string;
}

export interface CommentRow extends PublicComment {
  slug: string;
  email: string;
  status: 'pending' | 'approved';
}

export interface CommentRecipient {
  email: string;
  name: string;
}

export interface CommentPageQuery {
  status?: string;
  search?: string;
  limit?: number;
  offset?: number;
}

export interface CommentPage {
  total: number;
  rows: CommentRow[];
  limit: number;
  offset: number;
}

